diff --git a/.changeset/budget-provenance-types.md b/.changeset/budget-provenance-types.md
new file mode 100644
index 0000000..c7e40d3
--- /dev/null
+++ b/.changeset/budget-provenance-types.md
@@ -0,0 +1,5 @@
+---
+michi-core: minor
+---
+
+Added `BudgetSummary`, `SectionCost`, `ProvenanceBlock` and `ProvenanceEntry`: plain types for a response-level budget report and a provenance block, with builder methods, camelCase `serde::Serialize` behind the `serde` feature and `schemars::JsonSchema` behind `schemars`. They are not attached to `AgentResponse` yet.
diff --git a/.changeset/one-section-model.md b/.changeset/one-section-model.md
new file mode 100644
index 0000000..5d7edf2
--- /dev/null
+++ b/.changeset/one-section-model.md
@@ -0,0 +1,9 @@
+---
+michi-core: minor
+---
+
+michi-core: `AgentResponse` keeps its body in one list of sections. `items()` and `kv_items()` are shorthand that append a section named for the response's type, so calling both (or either twice) renders every body in call order instead of silently dropping one. The same applies to `@orin-dx/michi`'s `items()` and `kvItems()`.
+
+Breaking: removed `AgentResponse::render_toon()`, `render_kv()`, `total_count()` and `truncation()`, and NAPI `renderToon()`, `renderKv()` and `totalCount()`. A response with only `items()` or `kv_items()` renders the same text, with these exceptions: a `totalCount` line renders only when the total is larger than the rows returned (so an empty list no longer prints `totalCount: 0`), and `render(Json)` / `structuredContent` gain a `sections` array next to `body`.
+
+Migration: `AgentResponse::new(..).items(..).hints(..).render_toon()` becomes `.render(OutputFormat::Text)`; `.total_count(n)` becomes `Section::toon(name, fields, rows).total_count(Some(n))` passed to `.section(..)`; `.items(rows, f).truncation(&outcome, g)` becomes `.truncated_section(Section::toon(name, f, rows), &outcome, g)`. In JavaScript, `renderToon()` and `renderKv()` become `renderText()`, and `totalCount(n)` becomes the optional third argument of `items(rows, fields, n)` (second of `kvItems(items, n)`).
diff --git a/.changeset/response-envelope-wiring.md b/.changeset/response-envelope-wiring.md
new file mode 100644
index 0000000..82f87c6
--- /dev/null
+++ b/.changeset/response-envelope-wiring.md
@@ -0,0 +1,5 @@
+---
+michi-core: minor
+---
+
+michi-core: `AgentResponse::budget(BudgetSummary)` and `AgentResponse::provenance(ProvenanceBlock)` attach a response-level `budget:` block and `provenance:` block. A response now renders its sections, then `budget:`, `provenance:`, `help[]` and `recovery[]`; the per-section roll-up under `budget:` appears only when the response has two or more sections. `render(Json)` and `to_call_tool_result().structured_content` gain `sections`, `budget` and `provenance` keys, present only when set (a response with no section, budget or provenance keeps exactly `body`, `hints`, `recovery` and `isError`). When two or more sections cut cells or report a `totalCount`, each is now one merged TOON table with a leading `section` column (`truncated[N]{section,row,field,removed}:`, `totalCount[N]{section,total}:`) instead of repeating a root key, which TOON forbids.
diff --git a/.changeset/response-sections.md b/.changeset/response-sections.md
new file mode 100644
index 0000000..fb3cd8c
--- /dev/null
+++ b/.changeset/response-sections.md
@@ -0,0 +1,5 @@
+---
+michi-core: minor
+---
+
+michi-core: `AgentResponse` can hold several blocks. Add them with `.section(Section)`; a `Section` is a TOON list, a key-value block or a text fragment (`Section::toon`, `Section::kv`, `Section::text`), optionally with a pre-truncation `total_count`. Sections render in the order you add them, then `help[]` and `recovery[]`.
diff --git a/.config/nextest.toml b/.config/nextest.toml
new file mode 100644
index 0000000..70491c1
--- /dev/null
+++ b/.config/nextest.toml
@@ -0,0 +1,6 @@
+# The scaling tests compare wall times, so CPU contention (a parallel build, a busy CI runner) can fail one even
+# though the code is linear: a 10x run is preempted more often than a 1x run. A real O(n^2) regression takes ~100x as
+# long on every attempt, so retrying costs nothing but the false alarms. Nextest reports a pass after a retry as FLAKY.
+[[profile.default.overrides]]
+filter = 'binary(scaling)'
+retries = 2
diff --git a/crates/michi-core/src/toon/render.rs b/crates/michi-core/src/toon/render.rs
index a1a0429..4435f22 100644
--- a/crates/michi-core/src/toon/render.rs
+++ b/crates/michi-core/src/toon/render.rs
@@ -412,7 +412,7 @@ mod proof {
         /// and a cell was cut, michi adds one line to `help[]` pointing at that block and the caller's instruction.
         #[must_use]
         pub fn render(&self) -> String {
-            let (mut out, extra) = self.render_parts();
+            let (mut out, _, extra) = self.render_parts(true);
             let hints = self.opts.hints.iter().map(String::as_str).chain(extra.as_deref());
             let hints: Vec<&str> = hints.collect();
             crate::hints::append_help_block(&mut out, hints.into_iter());
@@ -422,27 +422,39 @@ mod proof {
         /// The document without its `help` block, plus the `help[]` line michi adds when it cut a cell and the
         /// caller set a truncation hint. [`AgentResponse`](crate::AgentResponse) merges that line into its own
         /// hints so a response keeps a single `help` key.
-        pub(crate) fn render_parts(&self) -> (String, Option<String>) {
+        ///
+        /// With `inline` the `truncated` block and `totalCount` line follow the list and the cut list returned is
+        /// empty. Without it the text is the list entry alone and the cuts come back as `(row, field name, chars
+        /// removed)`, so a multi-section response can merge the cuts of every block into one `truncated` table.
+        pub(crate) fn render_parts(&self, inline: bool) -> (String, Vec<(usize, String, usize)>, Option<String>) {
             let opts = self.opts;
             let capacity = 60 + opts.rows.len() * (opts.fields.len() * 12 + 10);
             let mut out = String::with_capacity(capacity);
             let cut = super::push_list(&mut out, opts);
-            super::push_truncated(&mut out, opts, &cut);
-            if let Some(total) = opts.total_count {
-                out.push_str("totalCount: ");
-                out.push_str(&total.to_string());
-                out.push('\n');
-            }
             let extra = match opts.truncation_hint.as_deref() {
                 Some(hint) if !cut.is_empty() && !hint.is_empty() => {
                     Some(format!("Cut cells are listed in the truncated block; use {hint} for the full value"))
                 }
                 _ => None,
             };
+            let mut cuts = Vec::new();
+            if inline {
+                super::push_truncated(&mut out, opts, &cut);
+                if let Some(total) = opts.total_count {
+                    out.push_str("totalCount: ");
+                    out.push_str(&total.to_string());
+                    out.push('\n');
+                }
+            } else {
+                cuts = cut
+                    .into_iter()
+                    .map(|(row, field, removed)| (row, opts.fields.get(field).cloned().unwrap_or_default(), removed))
+                    .collect();
+            }
             if out.ends_with('\n') {
                 out.pop();
             }
-            (out, extra)
+            (out, cuts, extra)
         }
     }
 }
