 }

 #[test]
-fn agent_response_truncation_sets_the_count_and_hint_together() {
+fn agent_response_truncated_section_sets_the_count_and_hint_together() {
     let outcome = truncate_by_count(vec![1, 2, 3, 4, 5], 2);
