     let out = r.render(OutputFormat::Text);
     assert_eq!(out, "blocks: []\ntotalCount: 1\nhelp[1]: showing 0 of 1; raise --budget");
     decode(&out).unwrap_or_else(|e| panic!("not conformant TOON 4.4: {e}\n{out}"));

