1092	    fn ac053_hints_replaces_rather_than_appends() {
1093	        let r = AgentResponse::new("t").hint("a").hints(vec![Hint::from("b")]);
1094	        let out = r.render_hints_only();
1095	        assert!(out.contains('b'), "got: {out}");
1096	        assert!(!out.contains('a'), "got: {out}");
1097	    }
1098	
1099	    // AC-038 (extended): json_escape_str's generic below-0x20 control-
1100	    // character branch (\u00XX), distinct from the dedicated \n/\r/\t arms.
1101	    #[test]
1102	    #[cfg(feature = "serde")]
1103	    fn ac038_control_character_below_0x20_is_escaped_and_json_stays_valid() {
1104	        let r = AgentResponse::new("t").hint("before\u{1}after");
1105	        let raw = r.render_json();
1106	        assert!(raw.contains(r"\u0001"), "got: {raw}");
1107	        let parsed: serde_json::Value = serde_json::from_str(&raw).expect("must be valid JSON");
1108	        assert_eq!(parsed["hints"][0].as_str().unwrap(), "before\u{1}after");
1109	    }
1110	
1111	    // AC-049: DEFAULT_TRUNCATE_CELLS is a public constant equal to 200.
1112	    #[test]
1113	    fn ac049_default_truncate_cells_is_200() {
1114	        assert_eq!(DEFAULT_TRUNCATE_CELLS, 200);
1115	    }
