1117	    // AC-050: without an explicit .truncate_cells_at() call, the default
1118	    // (200) boundary holds: 199 chars untruncated, 250 chars truncated.
1119	    #[test]
1120	    fn ac050_default_truncate_boundary_holds_without_explicit_call() {
1121	        let untruncated = AgentResponse::new("t").items(vec![vec![Value::from("x".repeat(199))]], &["c"]);
1122	        let out = untruncated.render(OutputFormat::Text);
1123	        let cell_line = out.lines().nth(1).expect("row line present");
1124	        assert!(cell_line.contains(&"x".repeat(199)), "199 chars must be untruncated, got: {cell_line:?}");
1125	
1126	        let truncated = AgentResponse::new("t").items(vec![vec![Value::from("x".repeat(250))]], &["c"]);
1127	        let out = truncated.render(OutputFormat::Text);
1128	        let cell_line = out.lines().nth(1).expect("row line present");
1129	        let value_part = cell_line.trim_start();
1130	        assert!(
1131	            value_part.chars().count() <= DEFAULT_TRUNCATE_CELLS,
1132	            "got line with {} chars: {cell_line:?}",
1133	            value_part.chars().count()
1134	        );
