                let parsed: serde_json::Value = serde_json::from_str(&json).expect("valid JSON");
                let obj = parsed.as_object().expect("top-level object");
                let mut keys: Vec<&str> = obj.keys().map(String::as_str).collect();
                keys.sort_unstable();
                assert_eq!(keys, want, "{json}");
