//! Repeatable response sections: several named blocks in one [`crate::AgentResponse`].

use crate::kv::KvItem;
use crate::toon::Value;

/// One named block within a response. A response may hold any number; they render in insertion order.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Section {
    /// The section's type name: the identifier at the head of its TOON line. KV and text bodies carry no heading, so
    /// the name only labels them for the caller.
    pub name: String,
    /// The section's contents.
    pub body: SectionBody,
    /// How many items this section carries, as set by the constructor. Rendering never trusts this field for `Toon`
    /// and `Kv` bodies: it counts `rows` / `items` itself (see [`Section::count`]). `Text` bodies keep the declared
    /// value, since michi cannot count items in prose.
    pub returned_count: usize,
    /// How many existed before truncation. `Some(n)` with `n > returned_count` renders `totalCount: n`.
    pub total_count: Option<usize>,
    /// Whether producing this section dropped anything. Carried for the caller; it does not change the text render.
    pub truncated: bool,
}

/// What a [`Section`] holds.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum SectionBody {
    /// A uniform list, rendered as a TOON list with the response's per-cell truncation applied.
    Toon {
        /// Ordered, distinct field names.
        fields: Vec<String>,
        /// Rows, parallel to `fields`.
        rows: Vec<Vec<Value>>,
    },
    /// A single receipt or a small set of labelled scalars.
    Kv(Vec<KvItem>),
    /// Prose or an already-rendered fragment, passed through unchanged. It is not escaped or validated: the caller
    /// owns its shape.
    Text(String),
}

impl Section {
    /// A TOON list section. `returned_count` is `rows.len()`.
    #[must_use]
    pub fn toon(name: impl Into<String>, fields: Vec<String>, rows: Vec<Vec<Value>>) -> Self {
        Self::with(name, rows.len(), SectionBody::Toon { fields, rows })
    }

    /// A key-value section. `returned_count` is `items.len()`.
    #[must_use]
    pub fn kv(name: impl Into<String>, items: Vec<KvItem>) -> Self {
        Self::with(name, items.len(), SectionBody::Kv(items))
    }

    /// A text section, passed through unchanged. `returned_count` starts at 1 for non-empty text and 0 for empty;
    /// set it with [`returned_count`](Self::returned_count).
    #[must_use]
    pub fn text(name: impl Into<String>, body: impl Into<String>) -> Self {
        let body = body.into();
        Self::with(name, usize::from(!body.is_empty()), SectionBody::Text(body))
    }

    fn with(name: impl Into<String>, returned_count: usize, body: SectionBody) -> Self {
        Self { name: name.into(), body, returned_count, total_count: None, truncated: false }
    }

    /// Record the pre-truncation count. `Some(n)` with `n` greater than the returned count renders `totalCount: n`.
    #[must_use]
    pub fn total_count(mut self, total: Option<usize>) -> Self {
        self.total_count = total;
        self
    }

    /// Record whether producing this section dropped anything.
    #[must_use]
    pub fn truncated(mut self, truncated: bool) -> Self {
        self.truncated = truncated;
        self
    }

    /// Declare how many items a `Text` body carries. Ignored for `Toon` and `Kv` bodies, whose count is derived.
    #[must_use]
    pub fn returned_count(mut self, n: usize) -> Self {
        if matches!(self.body, SectionBody::Text(_)) {
            self.returned_count = n;
        }
        self
    }

    /// The count rendering uses: `rows.len()` or `items.len()` for `Toon` and `Kv` bodies, the declared
    /// `returned_count` for `Text`. A hand-edited `returned_count` field cannot disagree with the body.
    #[must_use]
    pub fn count(&self) -> usize {
        match &self.body {
            SectionBody::Toon { rows, .. } => rows.len(),
            SectionBody::Kv(items) => items.len(),
            SectionBody::Text(_) => self.returned_count,
        }
    }

    /// The `totalCount` to render: `total_count` only when it exceeds [`count`](Self::count).
    pub(crate) fn shown_total(&self) -> Option<usize> {
        self.total_count.filter(|n| *n > self.count())
    }
}
//! Response-level budget report: what ceilings a caller worked under, what the response cost, and what each section
//! cost. michi renders a budget; it never computes one. See `docs/spec/07-wisp-and-monokl-envelope.md` §2.

use std::fmt::Write as _;

/// What a budget block renders: the ceilings a caller was working under, what the response cost against them, and
/// what that cost each section.
///
/// Every number is optional, so a caller who measured only tokens sets two fields and leaves the rest empty. Absent
/// fields are omitted from the rendered block, never written as `null`. `u64` rather than `usize` because these
/// values reach JSON, where a platform-dependent width means nothing.
///
/// `#[non_exhaustive]`: start from [`BudgetSummary::new`] or `Default` and use the builder methods.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
#[cfg_attr(feature = "schemars", schemars(rename_all = "camelCase"))]
#[non_exhaustive]
pub struct BudgetSummary {
    /// Token ceiling the caller set.
    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
    pub max_tokens: Option<u64>,
    /// Byte ceiling the caller set.
    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
    pub max_bytes: Option<u64>,
    /// Item ceiling the caller set.
    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
    pub max_items: Option<u64>,
    /// Tokens the response cost, as the caller measured it.
    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
    pub tokens_used: Option<u64>,
    /// Bytes the response cost, as the caller measured it.
    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
    pub bytes_used: Option<u64>,
    /// Whether the budget forced anything out of the response.
    pub truncated: bool,
    /// Per-section accounting, rendered in the order given.
    pub sections: Vec<SectionCost>,
}

impl BudgetSummary {
    /// An empty summary: no ceilings, no measurements, not truncated, no sections.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Set the token ceiling.
    #[must_use]
    pub fn max_tokens(mut self, n: u64) -> Self {
        self.max_tokens = Some(n);
        self
    }

    /// Set the byte ceiling.
    #[must_use]
    pub fn max_bytes(mut self, n: u64) -> Self {
        self.max_bytes = Some(n);
        self
    }

    /// Set the item ceiling.
    #[must_use]
    pub fn max_items(mut self, n: u64) -> Self {
        self.max_items = Some(n);
        self
    }

    /// Set the tokens the response cost.
    #[must_use]
    pub fn tokens_used(mut self, n: u64) -> Self {
        self.tokens_used = Some(n);
        self
    }

    /// Set the bytes the response cost.
    #[must_use]
    pub fn bytes_used(mut self, n: u64) -> Self {
        self.bytes_used = Some(n);
        self
    }

    /// Set whether the budget forced anything out of the response.
    #[must_use]
    pub fn truncated(mut self, truncated: bool) -> Self {
        self.truncated = truncated;
        self
    }

    /// Append one section's accounting line. Lines render in the order added.
    #[must_use]
    pub fn section(mut self, cost: SectionCost) -> Self {
        self.sections.push(cost);
        self
    }
}

/// One section's line in the budget roll-up.
///
/// `#[non_exhaustive]`: build it with [`SectionCost::new`] and the builder methods.
#[derive(Debug, Clone, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
#[cfg_attr(feature = "schemars", schemars(rename_all = "camelCase"))]
#[non_exhaustive]
pub struct SectionCost {
    /// The section's name.
    pub name: String,
    /// How many items the section returned.
    pub returned: u64,
    /// How many existed before truncation, when the caller knows.
    #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
    pub total: Option<u64>,
    /// Whether this section was cut.
    pub truncated: bool,
}

impl SectionCost {
    /// A section line with no known total, not truncated.
    #[must_use]
    pub fn new(name: impl Into<String>, returned: u64) -> Self {
        Self { name: name.into(), returned, total: None, truncated: false }
    }

    /// Set how many items existed before truncation.
    #[must_use]
    pub fn total(mut self, total: u64) -> Self {
        self.total = Some(total);
        self
    }

    /// Set whether this section was cut.
    #[must_use]
    pub fn truncated(mut self, truncated: bool) -> Self {
        self.truncated = truncated;
        self
    }
}

/// Render the `budget:` block, with no trailing newline. When `show_rollup` is set and there are sections, the
/// `sections[n]{name,returned,total,truncated}:` table follows. An unknown `total` is the TOON `null` cell, because a
/// table row needs a value in every column.
pub(crate) fn render_budget_block(b: &BudgetSummary, show_rollup: bool) -> String {
    let mut out = String::with_capacity(160 + b.sections.len() * 48);
    out.push_str("budget:");
    for (key, value) in numbers(b) {
        if let Some(n) = value {
            let _ = write!(out, "\n  {key}: {n}");
        }
    }
    let _ = write!(out, "\n  truncated: {}", b.truncated);
    if show_rollup && !b.sections.is_empty() {
        let _ = write!(out, "\nsections[{}]{{name,returned,total,truncated}}:", b.sections.len());
        for s in &b.sections {
            let _ = write!(out, "\n  {},{},", crate::toon::escape_value(&s.name), s.returned);
            match s.total {
                Some(t) => {
                    let _ = write!(out, "{t}");
                }
                None => out.push_str("null"),
            }
            let _ = write!(out, ",{}", s.truncated);
        }
    }
    out
}

/// The optional counters in render order.
fn numbers(b: &BudgetSummary) -> [(&'static str, Option<u64>); 5] {
    [
        ("tokensUsed", b.tokens_used),
        ("bytesUsed", b.bytes_used),
        ("maxTokens", b.max_tokens),
        ("maxBytes", b.max_bytes),
        ("maxItems", b.max_items),
    ]
}

/// The budget as a JSON object with camelCase keys. `sections` is always present; absent numbers are omitted.
pub(crate) fn budget_json(b: &BudgetSummary) -> String {
    let mut out = String::with_capacity(128 + b.sections.len() * 64);
    out.push('{');
    for (key, value) in numbers(b) {
        if let Some(n) = value {
            let _ = write!(out, "\"{key}\":{n},");
        }
    }
    let _ = write!(out, "\"truncated\":{},\"sections\":[", b.truncated);
    for (i, s) in b.sections.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str("{\"name\":");
        crate::kv::json_escape_str(&mut out, &s.name);
        let _ = write!(out, ",\"returned\":{}", s.returned);
        if let Some(t) = s.total {
            let _ = write!(out, ",\"total\":{t}");
        }

