        out.push_str(",\"value\":");
        crate::kv::json_escape_str(&mut out, &e.value);
        out.push('}');
    }
    out.push(']');
    if let Some(f) = &p.fingerprint {
        out.push_str(",\"fingerprint\":");
        crate::kv::json_escape_str(&mut out, f);
    }
    out.push('}');
    out
}

