// Shared differential probe body; `compat` is defined by the including file.
use michi_core::kv::{KvItem, KvValue};
use michi_core::toon::Value;
use michi_core::{truncate_by_count, truncate_by_size, AgentResponse, Audience, OutputFormat, RecoveryHint};

fn dump(label: &str, r: &AgentResponse) {
    println!("##### {label}");
    println!("[text]\n{}", r.render(OutputFormat::Text));
    println!("[json]\n{}", r.render(OutputFormat::Json));
    println!("[for-assistant]\n{}", r.render_for(Audience::Assistant));
    println!("[for-user]\n{}", r.render_for(Audience::User));
    println!("[ctr]\n{:?}", r.to_call_tool_result());
    println!("[is_error] {}", r.is_error());
}

fn kv(k: &str, v: KvValue) -> KvItem {
    KvItem::new(k, v)
}

fn main() {
    let rows = || vec![vec![Value::Int(1), Value::from("open")], vec![Value::Int(2), Value::from("日本語 ✓ \"q\", x")]];
    let f: &[&str] = &["id", "state"];
    dump("empty", &AgentResponse::new("issue"));
    dump("empty human", &AgentResponse::new("issue").human_content("hi"));
    dump("empty rows", &AgentResponse::new("issue").items(vec![], f));
    dump("empty rows no fields", &AgentResponse::new("issue").items(vec![], &[]));
    dump("rows", &AgentResponse::new("issue").items(rows(), f));
    dump("rows hints recovery", &AgentResponse::new("issue").items(rows(), f).hint("h1").hint("h, \"2\"").recovery_hint(RecoveryHint::new("retry").param("n", KvValue::Int(1)).reason("why")));
    dump("rows error", &AgentResponse::new("issue").items(rows(), f).as_error());
    dump("truncated cell default", &AgentResponse::new("t").items(vec![vec![Value::from("é".repeat(450))]], &["c"]));
    dump("truncated cell hint", &AgentResponse::new("t").truncate_cells_at(5).truncation_hint("full=true").items(vec![vec![Value::from("abcdefghij")], vec![Value::from("ab")]], &["c"]).hint("mine"));
    dump("truncated cap 0", &AgentResponse::new("t").truncate_cells_at(0).items(vec![vec![Value::from("abc")]], &["c"]));
    dump("invalid name help", &AgentResponse::new("help").items(rows(), f));
    dump("invalid name empty", &AgentResponse::new("help"));
    dump("row mismatch", &AgentResponse::new("t").items(vec![vec![Value::Int(1)]], f));
    dump("unicode name", &AgentResponse::new("日本 x").items(rows(), f));
    dump("floats", &AgentResponse::new("t").items(vec![vec![Value::Float(f64::NAN), Value::Float(1.5)], vec![Value::Null, Value::Bool(true)]], &["a", "b"]));
    dump("kv", &AgentResponse::new("t").kv_items(vec![kv("id", KvValue::Int(1)), kv("s", KvValue::Text("a\nb".into())), kv("m", KvValue::Missing)]));
    dump("kv hints human", &AgentResponse::new("t").kv_items(vec![kv("id", KvValue::Int(1))]).hint("h").human_content("x"));
    dump("kv empty", &AgentResponse::new("t").kv_items(vec![]));
    dump("kv empty hint", &AgentResponse::new("t").kv_items(vec![]).hint("h"));
    dump("kv dup", &AgentResponse::new("t").kv_items(vec![kv("a", KvValue::Int(1)), kv("a", KvValue::Int(2))]));
    dump("kv reserved", &AgentResponse::new("t").kv_items(vec![kv("help", KvValue::Int(1))]));
    dump("kv type name help", &AgentResponse::new("help").kv_items(vec![kv("a", KvValue::Int(1))]));
    dump("kv error", &AgentResponse::new("t").kv_items(vec![kv("a", KvValue::Int(1))]).as_error());
    for n in [0usize, 1, 2, 3, 100] {
        dump(&format!("rows total {n}"), &compat::items_total(AgentResponse::new("issue"), "issue", rows(), f, n));
        dump(&format!("empty rows total {n}"), &compat::items_total(AgentResponse::new("issue"), "issue", vec![], f, n));
        dump(&format!("kv total {n}"), &compat::kv_total(AgentResponse::new("t"), "t", vec![kv("a", KvValue::Int(1)), kv("b", KvValue::Int(2))], n));
        dump(&format!("kv empty total {n}"), &compat::kv_total(AgentResponse::new("t"), "t", vec![], n));
    }
    let o = truncate_by_count(vec![1i64, 2, 3, 4, 5], 2);
    let r = |kept: &[i64]| kept.iter().map(|n| vec![Value::Int(*n)]).collect::<Vec<_>>();
    dump("truncation cut", &compat::trunc(AgentResponse::new("issues").hint("x"), "issues", r(&o.kept), &["n"], &o, "pass --limit 5"));
    let o2 = truncate_by_count(vec![1i64, 2], 5);
    dump("truncation nocut", &compat::trunc(AgentResponse::new("issues"), "issues", r(&o2.kept), &["n"], &o2, "pass --limit 5"));
    let o3 = truncate_by_size(vec!["huge".to_string()], 1, String::len);
    dump("truncation nothing kept", &compat::trunc(AgentResponse::new("blocks"), "blocks", vec![], &["text"], &o3, "raise"));
    dump("truncation cut with cell cut", &compat::trunc(AgentResponse::new("issues").truncate_cells_at(3).truncation_hint("full"), "issues", vec![vec![Value::from("abcdef")]], &["n"], &o, "g"));
}

