import sys, re, json


def parse(p):
    cases = {}
    cur = None
    sec = None
    for line in open(p).read().split('\n'):
        if line.startswith('##### '):
            cur = line[6:]
            cases[cur] = {}
            sec = None
            continue
        m = re.match(r'^\[(text|json|for-assistant|for-user|ctr)\]$', line)
        if m:
            sec = m.group(1)
            cases[cur][sec] = []
            continue
        if line.startswith('[is_error]'):
            cases[cur]['is_error'] = line
            sec = None
            continue
        if sec:
            cases[cur][sec].append(line)
    return {k: {s: ('\n'.join(v) if isinstance(v, list) else v) for s, v in d.items()} for k, d in cases.items()}


a = parse(sys.argv[1])
b = parse(sys.argv[2])


def strip(j):
    o = json.loads(j)
    had = 'sections' in o
    o.pop('sections', None)
    return json.dumps(o), had


for k in a:
    for s in a[k]:
        x = a[k][s]
        y = b[k][s]
        if s == 'json':
            xs, _ = strip(x)
            ys, had = strip(y)
            if xs != ys:
                print(f"DIFF {k} [{s}] (excluding sections)\n  main={x}\n  head={y}")
            elif had:
                print(f"  note {k}: json gains sections only")
        elif s == 'ctr':
            if x != y:
                xm = re.sub(r'structured_content: ".*"', '', x)
                ym = re.sub(r'structured_content: ".*"', '', y)
                if xm != ym:
                    print(f"DIFF {k} [ctr non-structured]\n  main={x}\n  head={y}")
        elif x != y:
            print(f"DIFF {k} [{s}]\n  main={x!r}\n  head={y!r}")

